import java.net.*;import java.nio.file.*;public final class Bootstrap {public static void main(String[] args)throws Exception{var entries=System.getProperty("java.class.path").split(java.io.File.pathSeparator);var urls=new URL[entries.length];for(int i=0;i<entries.length;i++)urls[i]=Path.of(entries[i]).toUri().toURL();try(var loader=new URLClassLoader(urls,ClassLoader.getPlatformClassLoader())){Thread.currentThread().setContextClassLoader(loader);Class.forName("Verify",true,loader).getMethod("main",String[].class).invoke(null,(Object)args);}}}